import{_ as i,l as o,o as e,c as s,v as t,p as d,x as r,d as n,i as p,S as h}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"插头 DP","description":"","frontmatter":{"title":"插头 DP","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/plug-dp.md","filePath":"cs/plug-dp.md","lastUpdated":1789023840000}'),c={name:"cs/plug-dp.md"};function m(_,a,E,u,P,A){const l=o("Mermaid");return e(),s("div",null,[a[1]||(a[1]=t('<h1 id="插头-dp" tabindex="-1">插头 DP <a class="header-anchor" href="#插头-dp" aria-label="Permalink to &quot;插头 DP&quot;">​</a></h1><div class="epigraph"><p>网格路径/回路的轮廓线上，插头连通性用括号或最小表示压进哈希；逐格转移，状态在轮廓宽度上指数。</p><footer>—— 据网格轮廓线 DP 的标准技法；铺砖与回路计数整理</footer></div><p>上一课<a href="/cs/smawk">SMAWK</a>加速数值一层 DP。网格上哈密顿回路、连通铺砖，一行掩码只记录占用，不表达「哪些插头已经互连」。缺口是插头 DP：沿轮廓维护插头匹配。不重写状压一行兼容表。后课换根 DP 回到树。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>\\(n\\times m\\) 网格，要一条简单回路过指定格，或若干连通块。扫描到格 \\((i,j)\\) 时，已处理区域的边界（轮廓）上若干插头。转移：当前格是否把相邻插头接上、断开、或闭合一条回路。连通性用括号序列或并查集；同一连通的不同编号要最小表示，否则状态爆炸。</p><p>缺口是轮廓连通，不是 Held–Karp 的点子集。\\(m\\) 小 \\(n\\) 大则沿短边做轮廓，状态随 \\(m\\) 呈 Catalan 级而非单纯 \\(2^m\\)。</p><h3 id="不是普通状压铺砖" tabindex="-1">不是普通状压铺砖 <a class="header-anchor" href="#不是普通状压铺砖" aria-label="Permalink to &quot;不是普通状压铺砖&quot;">​</a></h3><p>无连通约束时，掩码兼容即可。有「必须整块连通/恰好一回路」才上插头。不要无连通也写并查集。</p><p><span class="marginnote">轮廓线思想用于铺砖更早；插头 DP 在竞赛中系统化。后课换根与网格无关。Kirchhoff 矩阵计生成树不在此。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>按行逐格。哈希表存当前轮廓状态的方案数或最优值。插头：空/左/右配对。合法转移后把轮廓平移一格。最后轮廓应无插头。</p>',11)),(e(),d(h,null,{default:r(()=>[p(l,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20CELL%5B%22%E9%80%90%E6%A0%BC%E6%89%AB%E6%8F%8F%22%5D%20--%3E%20PLUG%5B%22%E8%BD%AE%E5%BB%93%E6%8F%92%E5%A4%B4%22%5D%0A%20%20PLUG%20--%3E%20HASH%5B%22%E6%9C%80%E5%B0%8F%E8%A1%A8%E7%A4%BA%E5%93%88%E5%B8%8C%22%5D%0A%20%20HASH%20--%3E%20T%5B%22%E6%8E%A5%20%2F%20%E6%96%AD%20%2F%20%E9%97%AD%E5%9B%9E%E8%B7%AF%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>宽度 \\(m\\) 决定指数底，先估计状态数再写。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>逐格后轮廓平移，插头集合更新。平面匹配用括号。最小表示避免同一并查不同编号。与生成函数：可看成自动机，状态多则哈希。与状压：状压是插头 DP 在「无连通记忆」时的退化。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写全部插头题型模板。三维网格不写。后课默认：网格连通路径/回路用插头；无连通用状压。下一课换根 DP。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>轮廓插头表达连通；短边为宽。</li><li>最小表示 + 哈希。</li><li>无连通约束退回普通状压。</li><li>出处：轮廓线 DP 标准技法。</li></ul>',7))])}const B=i(c,[["render",m]]);export{f as __pageData,B as default};
